  ('UBSR-021','UBSR-022',625),('UBSR-023','UBSR-022',425),('UBSR-020','UBSR-022',695),('UBSR-042','UBSR-022',75),('UBSR-003','UBSR-022',50),
  ('UBSR-039','UBSR-047',895),('UBSR-038','UBSR-047',625),('UBSR-009','UBSR-047',305),('UBSR-002','UBSR-047',20),('UBSR-018','UBSR-047',125)
), resolved as (
  select p.id player_member_id,p.member_code,p.full_name,p.section,p.positions,p.base_price,a.final_price,t.id buyer_team_id,m.full_name buyer_manager_snapshot
  from final_auction a join public.league_members p on p.member_code=a.player_code join public.league_members m on m.member_code=a.manager_code join public.teams t on t.manager_member_id=m.id
)
insert into public.auction_log_entries(auction_round,player_member_id,player_code_snapshot,player_name_snapshot,section_snapshot,positions_snapshot,base_price,final_bought_price,buyer_team_id,buyer_manager_snapshot,outcome)
select 'Round 2 Complete',player_member_id,member_code,full_name,section,positions,base_price,final_price,buyer_team_id,buyer_manager_snapshot,'sold' from resolved
on conflict (auction_round,player_member_id) do nothing;

update public.auction_records ar set base_price=l.base_price,final_bought_price=l.final_bought_price,status='sold'::public.auction_status,buyer_team_id=l.buyer_team_id,resolved_at=l.logged_at,note='Finalized Round 2 auction; historical log stored separately.',updated_at=now() from public.auction_log_entries l where l.auction_round='Round 2 Complete' and ar.player_member_id=l.player_member_id;

insert into public.auction_records(player_member_id,base_price,final_bought_price,status,buyer_team_id,resolved_at,note)
select l.player_member_id,l.base_price,l.final_bought_price,'sold'::public.auction_status,l.buyer_team_id,l.logged_at,'Finalized Round 2 auction; historical log stored separately.' from public.auction_log_entries l where l.auction_round='Round 2 Complete'
on conflict (player_member_id) do nothing;

delete from public.roster_entries where source='auction';
insert into public.roster_entries(team_id,player_member_id,acquired_price,source)
select l.buyer_team_id,l.player_member_id,l.final_bought_price,'auction' from public.auction_log_entries l where l.auction_round='Round 2 Complete';

with balances(manager_code,balance) as (values ('UBSR-024',230),('UBSR-032',0),('UBSR-006',395),('UBSR-034',315),('UBSR-028',115),('UBSR-031',105),('UBSR-029',55),('UBSR-022',130),('UBSR-047',30))
update public.teams t set opening_balance=2000,current_balance=b.balance,updated_at=now() from balances b join public.league_members m on m.member_code=b.manager_code where t.manager_member_id=m.id;

insert into public.league_activity(category,headline,detail)
select 'auction','Round 2 auction finalized','45 players sold, 0 unsold, all 45 called. Total spent: 16,625 pts. The public auction log is finalized and immutable; the transfer market remains closed.'
where not exists (select 1 from public.league_activity where headline='Round 2 auction finalized');
